function refreshWaitStates(){const now=Date.now();document.querySelectorAll('[data-wait-start]').forEach(node=>{const started=Number(node.dataset.waitStart),left=Math.max(0,started+86400000-now),button=node.closest('.goal-card')?.querySelector('[data-action=wish-purchase]');if(left>0){node.textContent='Vuelve después de '+new Date(started+86400000).toLocaleString('es-CO');if(button)button.disabled=true;}else{node.textContent='¿Aún quieres este deseo?';if(button)button.disabled=false;}});}
