function nextPatternDate(today,day){const [year,month]=today.split('-').map(Number),currentDay=Number(today.slice(8));let targetYear=year,targetMonth=month;const lastThisMonth=new Date(year,month,0).getDate();let candidateDay=Math.min(day,lastThisMonth);if(candidateDay<=currentDay){targetMonth=month+1;if(targetMonth===13){targetMonth=1;targetYear+=1;}}const lastTargetMonth=new Date(targetYear,targetMonth,0).getDate();candidateDay=Math.min(day,lastTargetMonth);return targetYear+'-'+String(targetMonth).padStart(2,'0')+'-'+String(candidateDay).padStart(2,'0');}
