function importPreviewHTML(batch,origin='inbox',sourceText='',source='manual',format='auto'){const primary=origin==='movement'?'<button type="button" class="button button-primary" data-action="use-message-prefill">Usar en nuevo movimiento</button>':'<button type="button" class="button button-primary" data-action="import-batch">Guardar propuestas</button>';const retry=batch.errors.length&&sourceText?'<label class="field"><span>Texto para corregir las filas pendientes</span><textarea name="retryText" rows="6" autocomplete="off" spellcheck="false">'+escapeHTML(sourceText)+'</textarea></label><button type="submit" class="button button-secondary">Revisar texto actualizado</button>':'';return '<form data-form="inbox-preview" data-origin="'+escapeHTML(origin)+'" data-source="'+escapeHTML(source)+'" data-format="'+escapeHTML(format)+'" data-dirty="'+(retry?'true':'false')+'"><h3>Propuestas encontradas: '+batch.items.length+'</h3><p>Filas con error: '+batch.errors.length+' · Promociones omitidas: '+batch.ignored+'</p><ul>'+batch.items.slice(0,30).map(x=>'<li>'+escapeHTML(x.date||'Fecha pendiente')+' · '+escapeHTML(x.merchant||'Sin descripción')+' · '+(x.amountCents==null?'Importe pendiente':state.settings.hideBalances?'••••••':x.currency==='USD'?escapeHTML(formatMoney(Math.abs(x.amountCents))):escapeHTML((Math.abs(x.amountCents)/100).toFixed(2)))+' · '+escapeHTML(({expense:'Gasto',income:'Ingreso',transfer:'Transferencia',refund:'Reembolso',unknown:'Por clasificar'}[x.kind]||'Por clasificar'))+' · '+escapeHTML(x.currency||'Moneda pendiente')+(resolveInboxSuggestions(state,x,{today:localDate()}).duplicates.length?' · Posible duplicado':'')+'</li>').join('')+'</ul>'+(batch.errors.length?'<details open><summary>Ver errores</summary><ul>'+batch.errors.map(e=>'<li>Fila '+e.line+' · '+escapeHTML(e.field)+': '+escapeHTML(e.message)+'</li>').join('')+'</ul></details>':'')+(retry?'<p>El texto permanece aquí para que puedas corregir las filas no importadas.</p>'+retry:'<p>El texto original se descarta después de revisar. Las propuestas no cambian saldos ni experiencia.</p>')+(origin==='movement'?'<p>Revisa moneda, importe, fecha y cuenta. Solo se preparan campos; el movimiento se guarda cuando confirmes el formulario.</p>':'')+'<p data-form-error role="alert" hidden></p><div class="button-row">'+primary+'<button type="button" class="button button-secondary" data-action="close-sheet">Cancelar</button></div></form>';}
