dialog.addEventListener('change',async event=>{const input=event.target;if(input.matches('input[type=file][data-action=choose-backup]')&&input.files?.length)await restoreBackupFile(input);});
// Preserve a typed search and caret while refreshing the filtered list.
async function restoreBackupFile(input){const epoch=privacyEpoch;if(!privacySessionCurrent(epoch))return;const file=input.files[0];input.value='';if(file.size>5*1024*1024){formError(null,'El archivo supera el máximo de 5 MiB.');return;}let committed=false;try{const text=await file.text();if(!privacySessionCurrent(epoch))return;const backup=parseBackup(text),data=backup.data;const summary=data.accounts.length+' cuentas, '+data.movements.length+' movimientos, '+data.loans.length+' préstamos, '+data.recurring.length+' recurrentes y '+data.confirmations.length+' confirmaciones';if(!confirm('El respaldo contiene '+summary+'. ¿Reemplazar mis datos actuales? Esta acción no se puede deshacer.'))return;if(!privacySessionCurrent(epoch)||busy)return;busy=true;try{const next={...data,revision:state.revision+1};await store.commit(next,state.revision);committed=true;if(!privacySessionCurrent(epoch))return;state=next;closeSheet(true,true);paint();showToast('Respaldo restaurado.');}finally{busy=false;if(committed&&epoch!==privacyEpoch&&privacySessionCurrent(privacyEpoch))await reloadIfSafe();}}catch(error){if(privacySessionCurrent(epoch))formError(null,'No se pudo importar el respaldo. '+localizeError(error));}}
function refreshFilters(){const input=document.querySelector('#movement-search');const start=input?.selectionStart,end=input?.selectionEnd,focused=document.activeElement===input;query=input?.value||'';type=document.querySelector('#movement-type')?.value||'all';accountId=document.querySelector('#movement-account')?.value||'all';paint();if(focused){const next=document.querySelector('#movement-search');next?.focus();next?.setSelectionRange(start,end);}}
app.addEventListener('input',event=>{if(event.target.id==='movement-search')refreshFilters();});app.addEventListener('change',event=>{if(['movement-type','movement-account'].includes(event.target.id))refreshFilters();});
app.addEventListener('click',event=>{const a=event.target.closest('a[href^="#"]');if(a&&hasDraft()){event.preventDefault();if(confirm('Tienes cambios sin guardar. ¿Descartar el borrador y cambiar de sección?')){closeSheet(true);location.hash=a.getAttribute('href');}}});
window.addEventListener('hashchange',()=>{if(!allowNavigation()){history.replaceState(null,'',location.pathname+location.search+lastKnownHash);return;}const full=location.href,target=locationTarget(full);lastKnownHash=location.hash;if(target.quick){history.replaceState(null,'',location.pathname);lastKnownHash='';startQuickEntry(full);return;}if(target.route!==route||target.panel!==panel){route=target.route;panel=target.panel;paint();document.querySelector('#main-content')?.focus({preventScroll:true});}});
window.addEventListener('beforeunload',event=>{if(hasDraft()){event.preventDefault();event.returnValue='';}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState!=='visible'){pageHidden=true;privacyController?.lock({force:true});return;}pageHidden=false;privacyController?.refresh().then(()=>{if(privacyController?.locked)return;refreshWaitStates();reloadIfSafe();}).catch(()=>{});});window.addEventListener('pagehide',()=>{pageHidden=true;privacyController?.lock({force:true});});window.addEventListener('focus',()=>{privacyController?.refresh().then(()=>{if(!privacyController?.locked&&!pageHidden)reloadIfSafe();}).catch(()=>{});});window.addEventListener('pageshow',()=>{pageHidden=false;privacyController?.refresh().then(()=>{if(!privacyController?.locked)reloadIfSafe();}).catch(()=>{});});
function registerSync(){if('BroadcastChannel'in window&&!stateChannel){stateChannel=new BroadcastChannel('finanza-geek-state');stateChannel.onmessage=()=>reloadIfSafe();}store.onchange=()=>reloadIfSafe();}
function registerPWA(){if(pwaRegistered||!('serviceWorker'in navigator))return;pwaRegistered=true;navigator.serviceWorker.register('./sw.js').then(reg=>{if(reg.waiting){waitingWorker=reg.waiting;document.querySelector('#update-status').hidden=false;}reg.addEventListener('updatefound',()=>{const worker=reg.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller){waitingWorker=worker;document.querySelector('#update-status').hidden=false;}});});navigator.serviceWorker.addEventListener('controllerchange',()=>{if(shouldDeferUnsafeReload(hasDraft,busy)){controllerChangePending=true;document.querySelector('#update-status').hidden=false;showToast('Actualización lista. Se aplicará al guardar o cerrar el formulario.');return;}location.reload();});}).catch(()=>{});}
window.addEventListener('online',()=>{document.querySelector('#offline-status').hidden=true;});window.addEventListener('offline',()=>{document.querySelector('#offline-status').hidden=false;});if(!navigator.onLine)document.querySelector('#offline-status').hidden=false;
setInterval(()=>{refreshWaitStates();const day=localDate();if(day!==lastLocalDay){lastLocalDay=day;reloadIfSafe();}},1000);window.addEventListener('focus',()=>{refreshWaitStates();reloadIfSafe();});
start();
